#pragma once

#include "CoreMinimal.h"
#include "Dom/JsonObject.h"

class UIKRetargeter;
class UIKRigDefinition;
class USkeletalMesh;
struct FAnimMcpContext;
struct FAnimMcpError;

/**
 * IK Rig · IK Retargeter 생성 (AI 애니 생성 Phase 1 — Docs/AIAnimation/ArchitectureAudit.md §2 · §4 · §10 create_ik_rig / create_ik_retargeter).
 *
 * 엔진 경로 (5.7.4 소스) — 에디터 "Retarget Animations" 창의 자동 생성(FProceduralRetargetAssets, SRetargetAnimAssetsWindow.cpp:633-743)을
 * 그대로 따른다. 기존 RTG_KatanaToH · RTG_AutoGeneratedHandS(IK_AutoGenerated*) 가 이 경로의 산출물이다(감사 §4 의 7 op 구성):
 *   IK Rig  — SetSkeletalMesh → AutoGenerateRetargetDefinition → SetRetargetDefinition → AutoGenerateFBIK.
 *             템플릿이 맞지 않으면(bUsedTemplate 거짓) 체인 0개라 애셋을 만들기 전에 IKRIG_AUTO_FAILED + 본 계층을 돌려준다 → mode manual 로 체인 지정.
 *   RTG     — SetIKRig ×2 → RemoveAllOps → AddDefaultOps → (ops) 아래 레시피. 프리뷰 메시는 인자(필수)로.
 *     default        — 모든 op 의 체인 매핑을 정확한 이름(대소문자 무시)으로. auto_align 이면 타깃 리타깃 포즈 자동 정렬.
 *     match_existing — 에디터 자동 생성과 같다(체인 매핑만 다름): 모든 op 매핑 Exact(에디터는 FK op 만 — 꺼진 Run IK Rig 의 fuzzy 를 자동 정렬이 따른다) · 타깃 포즈 리셋 → AutoAlignAllBones(Target) → 템플릿의 자동 포즈 제외 본 리셋 ·
 *                      Run IK Rig 끔 · 루트 모션 op(타깃 루트≠펠비스면 소스가 루트 없을 때 펠비스에서 생성, 같으면 끔) · Pin Bones op(템플릿 핀 본,
 *                      전역 위치·회전 복사). 회귀 비교(완료 기준 2)용.
 *   align_mode — 타깃 포즈를 자동 정렬할 때(match_existing, default + auto_align): engine(기본, 위 그대로) | per_bone
 *                (엔진 정렬 뒤 뼈 수가 같은 체인을 FK 1:1 로 바꾸고 본 대 본 · 체인 끝까지 맞춘다 — AnimMcpRetargetPoseAlign.h).
 * 재사용은 existing_rig / existing_retargeter 를 줄 때만 — 호환성만 검사하고 쓰지 않는다.
 *
 * 정면 맞춤 (facing_yaw_deg ≠ 0) — FK · 펠비스 op 는 전역 델타(소스 현재 × 소스 기준⁻¹ × 대상 기준, FKChainsOp.cpp:343-350)이고
 * 소스 현재 포즈에는 리타깃 포즈가 적용되지 않는다(IKRetargetProcessor.cpp:1268-1316). 그래서 소스 쪽 포즈만 돌리면 동작 평면은 맞아도
 * 결과 전체가 소스 정면을 본다. 대신 대상 쪽에서:
 *   ① 대상 리타깃 포즈의 스켈레톤 루트(본 0, 펠비스 아님)를 −yaw → 풀이 동안 대상이 소스 정면을 본다(자동 정렬도 같은 정면에서 비교)
 *   ② Additive Pose op(RetargetPoseOp.cpp:66-128)를 Root Motion op 바로 앞에 — 루트를 +yaw 로 되돌리고 자식은 따라 돈다(펠비스 이동 포함)
 *   ③ Root Motion op 가 소스 루트를 복사하면 GlobalOffset 에 +yaw (RootMotionGeneratorOp.cpp:160 NewRoot * GlobalOffset)
 * 루트 회전이 기준 대비 Yaw 만일 때 정확하다. 대상 루트가 펠비스면 펠비스 이동이 돌지 않아 거부한다.
 */
namespace AnimMcpRetargetAssets
{
	struct FChainSpec
	{
		FName Name;
		FName Start;
		FName End;
		/** NAME_None 이면 IK 골 없음 */
		FName Goal;
	};

	/** chains[{name, start, end, goal?}] — 형식 오류는 BAD_REQUEST(details.field · index) */
	bool ParseChains(const TSharedRef<FJsonObject>& Params, TArray<FChainSpec>& Out, FAnimMcpError& OutError);

	struct FIKRigParams
	{
		/** 새로 만들 애셋 경로 (ExistingRig 가 없을 때 필수) */
		FString AssetPath;
		USkeletalMesh* Mesh = nullptr;
		UIKRigDefinition* ExistingRig = nullptr;
		bool bManual = false;
		/** NAME_None = auto 결과의 펠비스 (manual 은 필수) */
		FName Pelvis;
		TArray<FChainSpec> Chains;
		bool bFBIK = true;
		bool bSave = false;
	};

	/**
	 * {asset_path, reused, preview_mesh, template_match, pelvis, chains[], goals[], solvers[], finger_chain_suggestion{} (새로 만들 때 — AnimMcpFingerChains::Suggest:
	 * 손은 manual 인자 · 템플릿 체인의 팔 짝, 정할 체인에 없는 손가락 체인은 진단 FINGER_CHAINS_SUGGESTED, 같은 이름이 다른 본이면 FINGER_CHAINS_DIFFER), saved}.
	 * IKRIG_AUTO_FAILED details 에도 finger_chain_suggestion(위상으로 찾은 손)
	 */
	TSharedPtr<FJsonObject> CreateIKRig(const FIKRigParams& Params, FAnimMcpContext& Context, FAnimMcpError& OutError);

	enum class EOpsRecipe : uint8
	{
		Default,
		MatchExisting,
	};

	enum class EAlignMode : uint8
	{
		Engine,
		PerBone,
	};

	struct FRetargeterParams
	{
		FString AssetPath;
		UIKRigDefinition* SourceRig = nullptr;
		UIKRigDefinition* TargetRig = nullptr;
		USkeletalMesh* SourceMesh = nullptr;
		USkeletalMesh* TargetMesh = nullptr;
		UIKRetargeter* Existing = nullptr;
		EOpsRecipe Ops = EOpsRecipe::Default;
		bool bAutoAlign = false;
		/** 타깃 포즈 자동 정렬 방식 — 정렬하지 않는 레시피(default, auto_align 없음)에 PerBone 은 BAD_REQUEST */
		EAlignMode AlignMode = EAlignMode::Engine;
		/** 소스 정면을 대상 정면으로 돌리는 Yaw(°, UE +Z 축) — 0 이면 맞추지 않는다 */
		double FacingYawDeg = 0.0;
		bool bSave = false;
	};

	/** {asset_path, reused, ops_recipe, align_mode, source_rig, target_rig, source_mesh, target_mesh, ops[], chain_mapping{}, unmapped_target_chains[], pin_bones[], root_motion{}, retarget_poses{}, facing_alignment{}|null, pose_alignment{}|null, saved} */
	TSharedPtr<FJsonObject> CreateRetargeter(const FRetargeterParams& Params, FAnimMcpContext& Context, FAnimMcpError& OutError);

	TSharedRef<FJsonObject> DescribeIKRig(const UIKRigDefinition* Rig);
	TSharedRef<FJsonObject> DescribeRetargeter(const UIKRetargeter* Retargeter);
}
